   547      {
   548        snprintf(
   549            message,
   550            sizeof(message),
   551            "invalid %s \"%s\": %s",
   552            (string_flags & STRING_GFLAGS_HEXADECIMAL) ?
   553                "hex string" : "regular expression",
   554            identifier,
   555            re_error.message);
