   642        result = yr_re_ast_split_at_chaining_point(
   643            remainder_re_ast, &re_ast, &remainder_re_ast, &min_gap, &max_gap);
   644
   645        if (result != ERROR_SUCCESS)
   646          goto _exit;
   647
   648        prev_string = aux_string;
   649
   650        result = _yr_parser_write_string(
   651            identifier,
   652            string_flags,
   653            compiler,
   654            NULL,
   655            re_ast,
   656            &aux_string,
   657            &min_atom_quality_aux,
   658            &compiler->current_rule->num_atoms);
   659
   660        if (result != ERROR_SUCCESS)
   661          goto _exit;
   662
   663        if (min_atom_quality_aux < min_atom_quality)
   664          min_atom_quality = min_atom_quality_aux;
   665
   666        aux_string->g_flags |= STRING_GFLAGS_CHAIN_PART;
   667        aux_string->chain_gap_min = min_gap;
   668        aux_string->chain_gap_max = max_gap;
   669
   670        prev_string->chained_to = aux_string;
   671
   672        // prev_string is now chained to aux_string, an string chained
   673        // to another one can't have a fixed offset, only the head of the
   674        // string chain can have a fixed offset.
   675
   676        prev_string->g_flags &= ~STRING_GFLAGS_FIXED_OFFSET;
   677      }
   678    }
   679    else
   680    {
   681      result = _yr_parser_write_string(
   682          identifier,
   683          string_flags,
   684          compiler,
   685          str,
   686          NULL,
   687          string,
   688          &min_atom_quality,
   689          &compiler->current_rule->num_atoms);
   690
   691      if (result != ERROR_SUCCESS)
   692        goto _exit;
   693    }
   694
   695    if (!STRING_IS_ANONYMOUS(*string))
   696    {
   697      result = yr_hash_table_add(
   698        compiler->strings_table,
   699        identifier,
   700        NULL,

442  // yr_re_ast_split_at_chaining_point
   443  //
   444  // In some cases splitting a regular expression in two is more efficient that
   445  // having a single regular expression. This happens when the regular expression
   446  // contains a large repetition of any character, for example: /foo.{0,1000}bar/
   447  // In this case the regexp is split in /foo/ and /bar/ where /bar/ is "chained"
   448  // to /foo/. This means that /foo/ and /bar/ are handled as individual regexps
   449  // and when both matches YARA verifies if the distance between the matches
   450  // complies with the {0,1000} restriction.
   451
   452  // This function traverses the regexp's tree looking for nodes where the regxp
   453  // should be split.
   454  //
   455
   456  int yr_re_ast_split_at_chaining_point(
   457      RE_AST* re_ast,
   458      RE_AST** result_re_ast,
   459      RE_AST** remainder_re_ast,
   460      int32_t* min_gap,
   461      int32_t* max_gap)
   462  {
   463    RE_NODE* child;
   464    RE_NODE* concat;
   465
   466    int result;
   467
   468    *result_re_ast = re_ast;
   469    *remainder_re_ast = NULL;
   470    *min_gap = 0;
   471    *max_gap = 0;
   472
   473    if (re_ast->root_node->type != RE_NODE_CONCAT)
   474      return ERROR_SUCCESS;
   475
   476    child = re_ast->root_node->children_head;
   477
   478    while (child != NULL)
   479    {
   480      if (!child->greedy &&
   481           child->type == RE_NODE_RANGE_ANY &&
   482          (child->start > YR_STRING_CHAINING_THRESHOLD ||
   483           child->end > YR_STRING_CHAINING_THRESHOLD))
   484      {
   485        result = yr_re_ast_create(remainder_re_ast);
   486
   487        if (result != ERROR_SUCCESS)
   488          return result;
   489
   490        concat = yr_re_node_create(RE_NODE_CONCAT);
   491
   492        if (concat == NULL)
   493          return ERROR_INSUFFICIENT_MEMORY;
   494
   495        concat->children_head = re_ast->root_node->children_head;
   496        concat->children_tail = child->prev_sibling;
   497
   498        re_ast->root_node->children_head = child->next_sibling;
   499
   500        if (child->prev_sibling != NULL)
   501          child->prev_sibling->next_sibling = NULL;
   502
   503        if (child->next_sibling != NULL)
   504          child->next_sibling->prev_sibling = NULL;
   505
   506        *min_gap = child->start;
   507        *max_gap = child->end;
   508
   509        (*result_re_ast)->root_node = re_ast->root_node;
   510        (*result_re_ast)->flags = re_ast->flags;
   511        (*remainder_re_ast)->root_node = concat;
   512        (*remainder_re_ast)->flags = re_ast->flags;
   513
   514        yr_re_node_destroy(child);
   515
   516        return ERROR_SUCCESS;
   517      }
   518
   519      child = child->next_sibling;
   520    }
   521
   522    return ERROR_SUCCESS;
   523  }
